<?php
declare(strict_types=1); namespace App\Domain;
final readonly class OrderLine { public function __construct(public int $quantity, public float $unitPrice) { if ($quantity < 0 || $unitPrice < 0.0) { throw new \InvalidArgumentException('Quantity and unit price must be non-negative.'); } } public function total(): float { $subtotal = $this->quantity * $this->unitPrice; return round($subtotal, 2); } public function isEmpty(): bool { return $this->quantity === 0; } public function withQuantity(int $quantity): self { return new self($quantity, $this->unitPrice); } public function withUnitPrice(float $unitPrice): self { return new self($this->quantity, $unitPrice); } public function hasPrice(): bool { return $this->unitPrice > 0.0; } public function isFree(): bool { return $this->unitPrice === 0.0; } public function lineLabel(): string { return sprintf('%dx%.2f', $this->quantity, $this->unitPrice); } public function isBulk(): bool { return $this->quantity >= 10; } public function isSingle(): bool { return $this->quantity === 1; } public function volumeTier(): string { if ($this->quantity >= 100) { return 'wholesale'; } if ($this->quantity >= 10) { return 'bulk'; } return 'retail'; } }
